<?php
define('F2SB_ENGINE',true);
require __DIR__.'/../f2-backup-local/engine.php';
function check($ok,$message){if(!$ok)throw new RuntimeException('FAIL: '.$message);echo "PASS: $message\n";}
function advance($job,$until){for($i=0;$i<500;$i++){$s=F2SB_Engine::execute($job);if($s['phase']===$until)return $s;}throw new RuntimeException('Too many steps');}
$work=sys_get_temp_dir().'/f2-test-'.bin2hex(random_bytes(4));mkdir($work,0700);$root=$work.'/site';mkdir($root,0755);mkdir($root.'/wp-content',0755);mkdir($root.'/wp-content/uploads',0755);
file_put_contents($root.'/wp-config.php',"<?php /* preserved current connection */");
file_put_contents($root.'/index.php',"<?php echo 'original';\n");file_put_contents($root.'/.htaccess',"# original\n");
file_put_contents($root.'/wp-content/uploads/binary.dat',random_bytes(1024*1024));
mkdir($root.'/wp-content/uploads/empty-original',0750);
$binaryHash=hash_file('sha256',$root.'/wp-content/uploads/binary.dat');
$cfg=['host'=>'127.0.0.1:13306','user'=>'root','password'=>'','name'=>'f2_test','charset'=>'utf8mb4','flags'=>0];
$raw=new mysqli('127.0.0.1','root','','',13306);$raw->query('DROP DATABASE IF EXISTS f2_test');$raw->query('CREATE DATABASE f2_test CHARACTER SET utf8mb4');$raw->close();
$db=F2SB_Engine::db($cfg);
$db->query('CREATE TABLE wp_options (option_id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY, option_name varchar(191) UNIQUE, option_value longtext) ENGINE=InnoDB');
$db->query("INSERT INTO wp_options(option_name,option_value) VALUES ('home','https://example.test'),('siteurl','https://example.test')");
$serialized=serialize(['acentos'=>'Fábio, Flávia 🦋','url'=>'https://example.test','nested'=>['x'=>null,'false'=>false]]);
$q=$db->prepare('INSERT INTO wp_options(option_name,option_value) VALUES (?,?)');$key='serialized';$q->bind_param('ss',$key,$serialized);$q->execute();
$db->query('CREATE TABLE wp_data (id int PRIMARY KEY, raw_bytes longblob, title text, optional text NULL, doubled int GENERATED ALWAYS AS (id * 2) STORED) ENGINE=InnoDB');
$q=$db->prepare('INSERT INTO wp_data(id,raw_bytes,title,optional) VALUES (?,?,?,?)');
for($i=0;$i<800;$i++){$bin=random_bytes(32)."\0\xff'\\";$text="Linha $i: João e Fábio 🦋\n";$null=$i%2?'':null;$q->bind_param('isss',$i,$bin,$text,$null);$q->execute();}
$db->query('CREATE TABLE wp_child (id int PRIMARY KEY, parent_id int, CONSTRAINT child_fk FOREIGN KEY (parent_id) REFERENCES wp_data(id)) ENGINE=InnoDB');$db->query('INSERT INTO wp_child VALUES (1,5)');
$db->query('CREATE TABLE wp_legacy (id int, content text) ENGINE=MyISAM');$db->query("INSERT INTO wp_legacy VALUES (1,'sem chave'),(1,'sem chave')");
$db->query('CREATE TABLE other_app (id int)');$db->query('INSERT INTO other_app VALUES(42)');
$expected=[];foreach(F2SB_Engine::tables($db,'wp_') as $t)$expected[$t]=$db->query('SELECT * FROM '.F2SB_Engine::ident($t))->fetch_all(MYSQLI_ASSOC);
$job=$work.'/backup';mkdir($job,0700);$s=['type'=>'backup','phase'=>'db','root'=>$root,'created'=>gmdate('c'),'home'=>'https://example.test','siteurl'=>'https://example.test','prefix'=>'wp_','wp_version'=>'fixture','files'=>0,'bytes'=>0,'rows'=>0,'exclude'=>[],'tables'=>F2SB_Engine::tables($db,'wp_'),'table_i'=>0,'row_i'=>0,'schema_written'=>false];
F2SB_Engine::save($job.'/state.json',$s);F2SB_Engine::save($job.'/config.json',$cfg);
$s=advance($job,'done');check($s['files']===4,'Backup includes hidden file, configuration and binary upload');
$zip=new ZipArchive();check($zip->open($job.'/backup.zip')===true,'Valid ZIP opens');check($zip->numFiles===7,'ZIP has expected file and metadata count');check(hash('sha256',$zip->getFromName('site/wp-content/uploads/binary.dat'))===$binaryHash,'Binary ZIP content identical');$zip->close();
function restoreJob($work,$source,$root,$cfg,$suffix='restore'){$r=$work.'/'.$suffix;mkdir($r,0700);copy($source.'/backup.zip',$r.'/backup.zip');F2SB_Engine::save($r.'/config.json',$cfg);F2SB_Engine::save($r.'/state.json',['type'=>'restore','phase'=>'inspect','root'=>$root,'home'=>'https://example.test','siteurl'=>'https://example.test','prefix'=>'wp_','created'=>gmdate('c'),'exclude'=>[]]);advance($r,'ready');return $r;}
$r=restoreJob($work,$job,$root,$cfg);
check(!file_exists($root.'/.maintenance'),'Validation does not change live site');
file_put_contents($root.'/index.php','MUTATED');file_put_contents($root.'/wp-content/uploads/binary.dat','MUTATED');file_put_contents($root.'/extra.txt','PRESERVE EXTRA');file_put_contents($root.'/wp-config.php','CURRENT CONFIG');$db->query("UPDATE wp_options SET option_value='alterado' WHERE option_name='serialized'");$db->query('DELETE FROM wp_child');$db->query('DELETE FROM wp_data');$db->query('CREATE TABLE wp_extra_after_backup (id int)');
F2SB_Engine::execute($r,'begin');check(file_exists($root.'/.maintenance'),'Maintenance enabled during restore');
$rs=advance($r,'done');check(file_get_contents($root.'/index.php')==="<?php echo 'original';\n",'Core file restored');check(hash_file('sha256',$root.'/wp-content/uploads/binary.dat')===$binaryHash,'Binary media restored');check(file_get_contents($root.'/wp-config.php')==="<?php /* preserved current connection */",'Original wp-config restored');check(is_dir($root.'/wp-content/uploads/empty-original'),'Empty directory restored');check((fileperms($root.'/wp-content/uploads/empty-original')&0777)===0750,'Directory permissions restored');check(file_get_contents($root.'/extra.txt')==='PRESERVE EXTRA','Extra files retained when prune is disabled');check(!file_exists($root.'/.maintenance'),'Maintenance removed after success');
$db->close();$db=F2SB_Engine::db($cfg);
foreach($expected as $t=>$rows){$actual=$db->query('SELECT * FROM '.F2SB_Engine::ident($t))->fetch_all(MYSQLI_ASSOC);check($actual===$rows,'Exact database roundtrip: '.$t);}
check($db->query('SELECT id FROM other_app')->fetch_row()[0]==='42','Other application table untouched');check(!in_array('wp_extra_after_backup',F2SB_Engine::tables($db,'wp_'),true),'Extra prefixed tables removed from live namespace');
check($db->query("SHOW TABLES LIKE 'f2sb\\_%'")->num_rows===0,'Staged/old tables cleaned');
// Failure after applying files must roll back before database switch.
$r2=restoreJob($work,$job,$root,$cfg,'rollback');file_put_contents($root.'/index.php','ROLLBACK TARGET');F2SB_Engine::execute($r2,'begin');
for($i=0;$i<30;$i++){$st=F2SB_Engine::execute($r2);if($st['phase']==='switch')break;}
check($st['phase']==='switch','Reached file restore before database switch');$st=F2SB_Engine::execute($r2,'rollback');if($st['phase']!=='rolled_back')$st=advance($r2,'rolled_back');check(file_get_contents($root.'/index.php')==='ROLLBACK TARGET','Rollback restores previous files');check(!file_exists($root.'/.maintenance'),'Rollback clears maintenance');
// Reject dangerous archive paths before any live mutation.
foreach(['../escape','/absolute','a/../../x','a\\b','C:evil','a//b',"nul\0x"] as $bad){$caught=false;try{F2SB_Engine::relative($bad);}catch(Throwable $e){$caught=true;}check($caught,'Reject unsafe path '.json_encode($bad));}
$bad=$work.'/bad';mkdir($bad,0700);copy($job.'/backup.zip',$bad.'/backup.zip');$z=F2SB_Engine::zip($bad.'/backup.zip');$original=$z->getFromName('site/index.php');$z->addFromString('site/index.php',$original.'tampered');$z->close();F2SB_Engine::save($bad.'/config.json',$cfg);F2SB_Engine::save($bad.'/state.json',['type'=>'restore','phase'=>'inspect','root'=>$root,'home'=>'https://example.test','siteurl'=>'https://example.test','prefix'=>'wp_','created'=>gmdate('c'),'exclude'=>[]]);$caught=false;try{advance($bad,'ready');}catch(Throwable $e){$caught=true;}check($caught,'Tampered content rejected before restore');check(!file_exists($root.'/.maintenance'),'Invalid archive never enables maintenance');
// Simulate a crashed request. It must not replay rows/file mutations.
$r3=restoreJob($work,$job,$root,$cfg,'crash');F2SB_Engine::execute($r3,'begin');$st=F2SB_Engine::json($r3.'/state.json');$st['running']=true;F2SB_Engine::save($r3.'/state.json',$st);$caught=false;try{F2SB_Engine::execute($r3);}catch(Throwable $e){$caught=true;}check($caught,'Interrupted import is not automatically replayed');F2SB_Engine::execute($r3,'rollback');
// Exact restore removes extra files; rollback also recovers files removed by prune.
$r4=restoreJob($work,$job,$root,$cfg,'prune');$st=F2SB_Engine::json($r4.'/state.json');$st['prune']=true;F2SB_Engine::save($r4.'/state.json',$st);file_put_contents($root.'/extra.txt','EXTRA BEFORE PRUNE');F2SB_Engine::execute($r4,'begin');advance($r4,'switch');check(!is_file($root.'/extra.txt'),'Exact mode removes extra files');F2SB_Engine::execute($r4,'rollback');check(file_get_contents($root.'/extra.txt')==='EXTRA BEFORE PRUNE','Rollback recovers pruned files');
$r5=restoreJob($work,$job,$root,$cfg,'prune-complete');$st=F2SB_Engine::json($r5.'/state.json');$st['prune']=true;F2SB_Engine::save($r5.'/state.json',$st);F2SB_Engine::execute($r5,'begin');advance($r5,'done');check(!is_file($root.'/extra.txt'),'Exact restore completes with extra files removed');
// Recover the checkpoint on either side of the atomic database rename.
$r6=restoreJob($work,$job,$root,$cfg,'switch-not-executed');F2SB_Engine::execute($r6,'begin');$st=advance($r6,'switch');$st['phase']='switch_pending';$st['running']=true;F2SB_Engine::save($r6.'/state.json',$st);$caught=false;try{F2SB_Engine::execute($r6);}catch(Throwable $e){$caught=true;}check($caught,'Interrupted switch detects rename not executed');$st=F2SB_Engine::json($r6.'/state.json');check($st['failed_phase']==='switch','Unexecuted switch safely enables rollback');F2SB_Engine::execute($r6,'rollback');
$r7=restoreJob($work,$job,$root,$cfg,'switch-already-executed');F2SB_Engine::execute($r7,'begin');$st=advance($r7,'switch');$st['phase']='switch_pending';$st['running']=true;F2SB_Engine::save($r7.'/state.json',$st);$pairs=[];foreach($st['old'] as $a=>$b)$pairs[]=F2SB_Engine::ident($a).' TO '.F2SB_Engine::ident($b);foreach($st['map'] as $a=>$b)$pairs[]=F2SB_Engine::ident($b).' TO '.F2SB_Engine::ident($a);$db->query('SET FOREIGN_KEY_CHECKS=0');$db->query('RENAME TABLE '.implode(', ',$pairs));$st=advance($r7,'done');check($st['phase']==='done','Interrupted switch detects rename completed and safely finishes');
// Detect uncooperative external database writes while the site is paused.
$j2=$work.'/unstable';mkdir($j2,0700);$st=['type'=>'backup','phase'=>'pause','root'=>$root,'created'=>gmdate('c'),'home'=>'https://example.test','siteurl'=>'https://example.test','prefix'=>'wp_','wp_version'=>'fixture','files'=>0,'bytes'=>0,'rows'=>0,'exclude'=>[],'tables'=>F2SB_Engine::tables($db,'wp_'),'table_i'=>0,'row_i'=>0,'schema_written'=>false,'lock_id'=>'test-stability'];F2SB_Engine::save($j2.'/config.json',$cfg);F2SB_Engine::save($j2.'/state.json',$st);$st=F2SB_Engine::execute($j2);check(file_exists($root.'/.maintenance'),'New backup enters maintenance');$st['pause_until']=time()-1;F2SB_Engine::save($j2.'/state.json',$st);advance($j2,'files');$db->query("UPDATE wp_options SET option_value='external writer' WHERE option_name='serialized'");$caught=false;try{advance($j2,'done');}catch(Throwable $e){$caught=str_contains($e->getMessage(),'banco mudou');}check($caught,'External database mutation rejects the backup');check(!file_exists($root.'/.maintenance'),'Rejected backup releases maintenance');
// Exact restore handles both file-to-directory and directory-to-file changes.
$r8=restoreJob($work,$job,$root,$cfg,'type-conflicts');unlink($root.'/index.php');mkdir($root.'/index.php');file_put_contents($root.'/index.php/extra.txt','restore this on rollback');rmdir($root.'/wp-content/uploads/empty-original');file_put_contents($root.'/wp-content/uploads/empty-original','this became a file');$st=F2SB_Engine::json($r8.'/state.json');$st['prune']=true;F2SB_Engine::save($r8.'/state.json',$st);F2SB_Engine::execute($r8,'begin');advance($r8,'switch');check(is_file($root.'/index.php')&&is_dir($root.'/wp-content/uploads/empty-original'),'Restore resolves changed path types');F2SB_Engine::execute($r8,'rollback');check(is_dir($root.'/index.php')&&file_get_contents($root.'/index.php/extra.txt')==='restore this on rollback','Rollback recovers original directory conflict');check(is_file($root.'/wp-content/uploads/empty-original'),'Rollback recovers original file conflict');
echo 'Peak memory: '.round(memory_get_peak_usage(true)/1048576,2)." MiB\n";echo 'Fixture: '.$work."\nALL INTEGRATION CHECKS PASSED\n";
